import json,numpy as np
m=json.load(open('/app/output/turn_toward_open_side_02/meta.json'));c=m['cameras']['robot_r1:zed_link:Camera:0'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];t=E[:,3];o=-R.T@t
print('cam',o)
for uv in [(170,130),(170,145),(150,120),(190,135),(120,130),(100,130)]:
 d=R.T@np.linalg.inv(K)@np.array([*uv,1.]);
 print('uv',uv,'dir',np.round(d,3))
 for z in [.8,.9,1.]:
  tt=(z-o[2])/d[2];print(' ',z,np.round(o+tt*d,3))
PY

